import { useNavigate } from 'react-router-dom';

export default function DomainsPage() {
  const navigate = useNavigate();

  const resetProgress = () => {
    localStorage.setItem("xp", "0");
    localStorage.setItem("currentDay", "1");
    localStorage.setItem("carryForward", JSON.stringify([]));
    localStorage.setItem("completedDays", JSON.stringify([]));
    localStorage.setItem("weeklyProgress", JSON.stringify({}));
  };

  const handleDomainSelect = (domain) => {
    localStorage.setItem("selectedDomain", domain);

    // 🔥 RESET PROGRESS FOR NEW DOMAIN
    resetProgress();

    navigate(`/quiz?path=domains&domain=${domain}`);
  };

  const domains = [
    "ai-and-ml",
    "web-development",
    "cloud-and-devops",
    "cybersecurity",
    "data-science",
    "mobile-development",
  ];

  return (
    <div className="grid gap-6 sm:grid-cols-2">
      {domains.map((domain) => (
        <button
          key={domain}
          onClick={() => handleDomainSelect(domain)}
          className="rounded-[2rem] border border-slate-300 bg-gradient-to-br from-blue-100 to-blue-50 p-6 shadow-md hover:shadow-lg transition dark:border-slate-600 dark:from-slate-800 dark:to-slate-800 text-left"
        >
          <h3 className="text-xl font-semibold capitalize text-slate-900 dark:text-slate-50">
            {domain.replace(/-/g, " ")}
          </h3>
        </button>
      ))}
    </div>
  );
}
